#include <iostream>
#include <iomanip>
#include <cmath>

using namespace std;

/**
 * 題目 10422: Is This Integration?
 * 在一個邊長為 a 的正方形中，以四個頂點為圓心、a 為半徑畫弧。
 * 求解三種不同區域的總面積：
 * 1. 中間的區塊 (area1)
 * 2. 四個「花瓣」形狀的區塊 (area2)
 * 3. 四個角落剩下的區塊 (area3)
 * 
 * 利用幾何關係可導出公式：
 * 令 x = area1, y = area2/4, z = area3/4
 * 1) x + 4y + 4z = a^2 (正方形總面積)
 * 2) x + 3y + 2z = (pi/4) * a^2 (扇形面積)
 * 3) x + 2y + z = (pi/12 + 1 - sqrt(3)/4) * a^2 (兩扇形相交部分)
 * 
 * 解得：
 * area1 = a^2 * (1 - sqrt(3) + pi/3)
 * area2 = a^2 * (2*sqrt(3) + pi/3 - 4)
 * area3 = a^2 * (4 - sqrt(3) - 2*pi/3)
 */

int main() {
    double a;
    const double PI = acos(-1.0);
    while (cin >> a) {
        double area1 = a * a * (1.0 - sqrt(3.0) + PI / 3.0);
        double area2 = a * a * (2.0 * sqrt(3.0) + PI / 3.0 - 4.0);
        double area3 = a * a * (4.0 - sqrt(3.0) - 2.0 * PI / 3.0);

        cout << fixed << setprecision(3) << area1 << " " << area2 << " " << area3 << endl;
    }
    return 0;
}
